@media (max-width:767px){.wstitancrep__v{padding:0 16px}}
/* /dizajn.py */
.wstitancrep__v>.wstitancrep__zak{text-align:center}
</style>
<script>
(function(){document.querySelectorAll('.wstitancrep__kar').forEach(function(k){
  var w=document.createElement('div');w.className='wstitancrep__karw';k.parentNode.insertBefore(w,k);w.appendChild(k);
  ['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wstitancrep__pus wstitancrep__pus--'+s;b.setAttribute('aria-label',s==='l'?'Prethodno':'Sljedeće');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
    b.addEventListener('click',function(){var x=k.firstElementChild;var d=x?x.getBoundingClientRect().width+22:300;k.scrollBy({left:s==='l'?-d:d,behavior:'smooth'});});w.appendChild(b);});
});})();
</script>
